	du.SetAllFilenames(names)

	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()

	// Feed all volumes at once.
	for _, name := range names {
		du.Add(ctx, name, filepath.Join(workDir, name))
	}

	du.Wait()

	results := du.Results()
	failures := du.Failures()
