func TestDirectUnpack_Abort(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	// Copy multi-volume parts.
	var names []string
	for i := 1; i <= 10; i++ {
		name := fmt.Sprintf("multi_new.part%02d.rar", i)
		copyRAR(t, srcDir, workDir, name)
		names = append(names, name)
	}

	// Use OnLine to detect when extraction has started.
	onLine, started := waitForStarted()

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{OnLine: onLine},
	)

	du.SetAllFilenames(names)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	// Feed vol 1 only — extraction will start and block on vol 2 via WaitFS.
	du.Add(ctx, "multi_new.part01.rar", filepath.Join(workDir, "multi_new.part01.rar"))

	// Wait for extraction to begin (OnLine fires when first file extracts from vol 1).
	select {
	case <-started:
	case <-time.After(5 * time.Second):
		// Even if no files extract from vol 1 alone, the goroutine started.
		// Continue with abort test.
	}

	// Abort instead of feeding remaining volumes.
	du.Abort()

	done := make(chan struct{})
	go func() {
		du.Wait()
		close(done)
	}()

	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("Wait() did not return after Abort()")
	}

	// Results should be empty after abort.
	results := du.Results()
	if len(results) != 0 {
		t.Fatalf("expected empty results after abort, got %d", len(results))
	}
}

func TestDirectUnpack_ContextCancel(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	var names []string
	for i := 1; i <= 10; i++ {
		name := fmt.Sprintf("multi_new.part%02d.rar", i)
		copyRAR(t, srcDir, workDir, name)
		names = append(names, name)
	}

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	du.SetAllFilenames(names)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)

	// Feed vol 1 only — extraction will block on WaitFS for vol 2.
	du.Add(ctx, "multi_new.part01.rar", filepath.Join(workDir, "multi_new.part01.rar"))

	// Let extraction start.
	time.Sleep(200 * time.Millisecond)

	// Cancel context — WaitFS.Open() should return ctx.Err().
	cancel()

	done := make(chan struct{})
	go func() {
		du.Wait()
		close(done)
	}()

	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("Wait() did not return after context cancel")
	}
}

