func TestDirectUnpack_AddAfterKilled(t *testing.T) {
	du := New(testLogger(t), "test", "/tmp", "/tmp", Options{})
	du.killed = true
	close(du.done) // so Abort() doesn't block
	ctx := context.Background()
	du.Add(ctx, "movie.part01.rar", "/tmp/movie.part01.rar")
	if du.started {
		t.Error("should not start after killed")
	}
}

func TestDirectUnpack_Abort_RecordsFailures(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	// Copy multi-volume parts plus a second set's vol.
	var names []string
	for i := 1; i <= 10; i++ {
		name := fmt.Sprintf("multi_new.part%02d.rar", i)
		copyRAR(t, srcDir, workDir, name)
		names = append(names, name)
	}
	// Add a "second set" (single_rar5 has different setname).
	copyRAR(t, srcDir, workDir, "single_rar5.rar")
	names = append(names, "single_rar5.rar")

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	du.SetAllFilenames(names)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	// Start multi_new (vol 1), queue single_rar5.
	du.Add(ctx, "multi_new.part01.rar", filepath.Join(workDir, "multi_new.part01.rar"))
	du.Add(ctx, "single_rar5.rar", filepath.Join(workDir, "single_rar5.rar"))

	// Let goroutine start.
	time.Sleep(200 * time.Millisecond)

	// Abort — should record failures for both sets.
	du.Abort()

	failures := du.Failures()
	if len(failures) < 2 {
		t.Fatalf("expected 2 failures (multi_new + single_rar5), got %d: %+v",
			len(failures), failures)
	}

	if f, ok := failures["multi_new"]; !ok {
		t.Error("expected failure for 'multi_new'")
	} else if !strings.Contains(f.Reason, "aborted") && !strings.Contains(f.Reason, "killed") && !strings.Contains(f.Reason, "cancel") {
		t.Errorf("expected abort/kill-related reason for multi_new, got: %q", f.Reason)
	}

	if f, ok := failures["single_rar5"]; !ok {
		t.Error("expected failure for 'single_rar5'")
	} else if !strings.Contains(f.Reason, "aborted") {
		t.Errorf("expected 'aborted' reason for single_rar5, got: %q", f.Reason)
	}

	// Results should be empty after abort.
	results := du.Results()
	if len(results) != 0 {
		t.Fatalf("expected empty results after abort, got %d", len(results))
	}
}

func TestDirectUnpack_OnLineCallback(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	volPath := copyRAR(t, srcDir, workDir, "single_rar5.rar")

	var mu sync.Mutex
	var lines []string
	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{
			OnLine: func(line string) {
				mu.Lock()
				lines = append(lines, line)
				mu.Unlock()
			},
		},
	)

	du.SetAllFilenames([]string{"single_rar5.rar"})

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	du.Add(ctx, "single_rar5.rar", volPath)
	du.Wait()

	mu.Lock()
	lineCount := len(lines)
	mu.Unlock()

	if lineCount == 0 {
		t.Error("expected OnLine callback to receive output lines")
	}

	results := du.Results()
	failures := du.Failures()
	if len(failures) != 0 {
		t.Fatalf("expected no failures, got: %+v", failures)
	}
	if len(results) == 0 {
		t.Fatal("expected success, got 0 results")
	}
}

