// TestDirectUnpack_SkipsNonRAR verifies that DirectUnpack pre-checks the
// magic bytes of the first volume and skips (rather than fails) sets that
// aren't RAR3 or RAR5 (the only formats rarengine can read). Other formats
// are handled by the normal unpack stage's external unrar fallback.
func TestDirectUnpack_SkipsNonRAR(t *testing.T) {
	workDir := t.TempDir()
	extractDir := t.TempDir()

	// A file starting with the ZIP local file header signature (PK\x03\x04).
	// DirectUnpack must reject this before invoking rarengine, so the
	// remaining bytes don't need to form a valid archive.
	data := []byte{0x50, 0x4b, 0x03, 0x04, 0xb2, 0xef, 0x73}
	volPath := filepath.Join(workDir, "notrar.rar")
	if err := os.WriteFile(volPath, data, 0o644); err != nil {
		t.Fatalf("write notrar.rar: %v", err)
	}

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	du.SetAllFilenames([]string{"notrar.rar"})

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	du.Add(ctx, "notrar.rar", volPath)
	du.Wait()

	if results := du.Results(); len(results) != 0 {
		t.Fatalf("expected no successful sets, got: %+v", results)
	}
	if failures := du.Failures(); len(failures) != 0 {
		t.Fatalf("expected no failed sets, got: %+v", failures)
	}

	skipped := du.Skipped()
	s, ok := skipped["notrar"]
	if !ok {
		t.Fatalf("expected 'notrar' to be recorded as skipped, got: %+v", skipped)
	}
	if !strings.Contains(s.Reason, "RAR3/RAR5") {
		t.Errorf("expected skip reason to mention RAR3/RAR5, got: %q", s.Reason)
	}
}

// waitForGoroutines polls runtime.NumGoroutine() until it drops to at most
// target, or fails the test when the deadline elapses. This is a
// poll-until-condition guard (no fixed time.Sleep for synchronization); the
// only time-based element is the deadline that t.Fatals, which is permitted.
func waitForGoroutines(t *testing.T, target int, deadline time.Duration, msg string) {
	t.Helper()
	timeout := time.After(deadline)
	for {
		runtime.GC() // let any just-finished goroutines be observed as gone
		if runtime.NumGoroutine() <= target {
			return
		}
		select {
		case <-timeout:
			t.Fatalf("%s: goroutines did not return to baseline %d within %s (now %d)",
				msg, target, deadline, runtime.NumGoroutine())
		default:
			// Yield to the scheduler and wait a tiny bit before re-checking to avoid CPU pegging.
			time.Sleep(10 * time.Millisecond)
		}
	}
}

// TestDirectUnpack_ExtractSet_FeederNoLeakOnEarlyError proves that when
// extractSet returns early because extractEntries fails, the volume feeder
// goroutine started by startVolumeFeed is unblocked and exits promptly rather
// than leaking (along with the *os.File it holds) until the job context is
// cancelled.
//
// Setup that guarantees the feeder is still alive at the moment of the early
// return: totalVolumes is set to 10 but only volume 1 is present on disk, so
// the feeder must either still be trying to send volume 1 on the unbuffered
// volumesChan, or be blocked in waitForVolume awaiting volume 2. The early
// error is triggered deterministically by making extractDir read-only, so the
// first os.OpenFile/MkdirAll inside extractEntries fails immediately,
// independent of rarengine streaming timing.
//
// On the unfixed code (extractSet watches only the caller ctx and never
// cancels on its own early return), the feeder stays blocked forever and this
// test fails at the deadline. With the WithCancel/defer cancel() fix, the
// feeder's ctx.Done() / waitForVolume select fires and the goroutine exits.
func TestDirectUnpack_ExtractSet_FeederNoLeakOnEarlyError(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	vol1 := copyRAR(t, srcDir, workDir, "multi_new.part01.rar")

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	const setname = "multi_new"
	// Volume 1 present and recorded; declare 10 total so the feeder always has
	// more work pending after volume 1.
	du.mu.Lock()
	du.totalVolumes[setname] = 10
	du.completedVols[setname] = map[int]string{1: vol1}
	du.mu.Unlock()

	// Force the early error: an unwritable extract directory makes the first
	// file write in extractEntries fail before any volume-2 data is needed.
	if err := os.Chmod(extractDir, 0o500); err != nil {
		t.Fatalf("chmod extractDir: %v", err)
	}
	t.Cleanup(func() { _ = os.Chmod(extractDir, 0o700) })

	// Quiesce so the baseline excludes scheduler-transient goroutines.
	runtime.GC()
	baseline := runtime.NumGoroutine()

	ctx := t.Context()

	errCh := make(chan error, 1)
	go func() {
		errCh <- du.extractSet(ctx, setname)
	}()

	select {
	case err := <-errCh:
		if err == nil {
			t.Fatal("expected extractSet to return an error (unwritable extractDir), got nil")
		}
	case <-time.After(5 * time.Second):
		t.Fatal("extractSet did not return within 5s")
	}

	// extractSet has returned. On fixed code its deferred cancel has already
	// fired, so the feeder must be gone. Poll back to baseline (one feeder
	// goroutine above baseline is the leak). The deadline t.Fatal is the only
	// time-based element and is allowed as a guard.
	waitForGoroutines(t, baseline, 5*time.Second,
		"feeder goroutine leaked after extractSet early return")
}

func TestDirectUnpack_Status(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	volPath := copyRAR(t, srcDir, workDir, "single_rar5.rar")

	var statusChanges int
	var mu sync.Mutex
	onStatusChange := func() {
		mu.Lock()
		statusChanges++
		mu.Unlock()
	}

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{
			OnStatusChange: onStatusChange,
		},
	)

	// Initial status check.
	initStatus := du.Status()
	if initStatus.Active {
		t.Error("expected initial status to be inactive")
	}
	if initStatus.CurrentSet != "" {
		t.Errorf("expected empty CurrentSet, got %q", initStatus.CurrentSet)
	}

	du.SetAllFilenames([]string{"single_rar5.rar"})

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	du.Add(ctx, "single_rar5.rar", volPath)

	// Check status during extraction.
	var activeStatus Status
	foundActive := false
	for start := time.Now(); time.Since(start) < 2*time.Second; {
		st := du.Status()
		if st.Active {
			activeStatus = st
			foundActive = true
			break
		}
		time.Sleep(10 * time.Millisecond)
	}

	if !foundActive {
		t.Error("never observed active direct unpack status")
	} else {
		if activeStatus.CurrentSet != "single_rar5" {
			t.Errorf("expected CurrentSet to be 'single_rar5', got %q", activeStatus.CurrentSet)
		}
		if activeStatus.TotalVolumes != 1 {
			t.Errorf("expected TotalVolumes to be 1, got %d", activeStatus.TotalVolumes)
		}
	}

	du.Wait()

	// Final status check.
	finalStatus := du.Status()
	if finalStatus.Active {
		t.Error("expected final status to be inactive")
	}
	if len(finalStatus.SuccessSets) != 1 || finalStatus.SuccessSets[0] != "single_rar5" {
		t.Errorf("expected success sets to be ['single_rar5'], got %+v", finalStatus.SuccessSets)
	}

	mu.Lock()
	changes := statusChanges
	mu.Unlock()
	if changes == 0 {
		t.Error("expected status changes callback to be called, got 0")
	}
}

func TestDirectUnpack_Status_FailedReasons(t *testing.T) {
	workDir := t.TempDir()
	extractDir := t.TempDir()

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	du.SetAllFilenames([]string{"corrupt.rar"})

	// Mark corrupt to force failure
	du.MarkCorrupt("corrupt", "failed articles")
	du.Add(context.Background(), "corrupt.rar", filepath.Join(workDir, "corrupt.rar"))

	du.Wait()

	status := du.Status()
	if len(status.FailedSets) != 1 || status.FailedSets[0] != "corrupt" {
		t.Errorf("expected failed sets to be ['corrupt'], got %+v", status.FailedSets)
	}
	if reason, ok := status.FailedReasons["corrupt"]; !ok || reason != "directunpack: failed articles" {
		t.Errorf("expected FailedReasons['corrupt'] to be 'directunpack: failed articles', got %q (ok=%t)", reason, ok)
	}
}

